package org.zhixiaoce.aperture;

import android.app.Activity;
import android.os.Handler;
import android.os.Looper;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Same-window channel picker: preview text/art never starts a second decoder. */
final class CinemaLivePanel implements AutoCloseable {
    interface Select {void select(int index);}
    private final Activity activity;private final List<CinemaCatalog.Channel> channels;private final List<String> groups=new ArrayList<>();private final List<Integer> visible=new ArrayList<>();private final int[] numbers;private final Select select;private final Runnable dismissed;private final LinearLayout panel,rows;private final TextView heading,preview,digits;private final ImageView logo;private final CinemaArtwork artwork;private final Handler main=new Handler(Looper.getMainLooper());
    private final boolean allowHttp;private CinemaEpg guide=new CinemaEpg();private int group,selected;private String entered="";private boolean closed;
    private final Runnable hide=()->hide();private final Runnable tune=()->tune();
    CinemaLivePanel(Activity a,FrameLayout stage,List<CinemaCatalog.Channel> channels,CinemaArtwork artwork,boolean allowHttp,Select select,Runnable dismissed){
        activity=a;this.allowHttp=allowHttp;this.channels=new ArrayList<>(channels);this.artwork=artwork;this.select=select;this.dismissed=dismissed;numbers=CinemaChannelNumbers.assign(channels);for(CinemaCatalog.Channel c:channels)if(!groups.contains(c.group))groups.add(c.group);
        panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(TvUi.dp(a,16),TvUi.dp(a,18),TvUi.dp(a,16),TvUi.dp(a,18));android.graphics.drawable.GradientDrawable glass=TvUi.glass(a,false);glass.setAlpha(235);panel.setBackground(glass);stage.addView(panel,new FrameLayout.LayoutParams(Math.round(a.getResources().getDisplayMetrics().widthPixels*.34f),-1,Gravity.RIGHT));panel.setVisibility(View.GONE);
        heading=TvUi.text(a,"",24,false);heading.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,34*a.getResources().getDisplayMetrics().heightPixels/1080f);panel.addView(heading);preview=TvUi.text(a,"",19,true);preview.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,26*a.getResources().getDisplayMetrics().heightPixels/1080f);preview.setMaxLines(3);logo=new ImageView(a);logo.setScaleType(ImageView.ScaleType.FIT_START);panel.addView(logo,new LinearLayout.LayoutParams(TvUi.dp(a,80),TvUi.dp(a,36)));panel.addView(preview);
        ScrollView scroll=new ScrollView(a);rows=new LinearLayout(a);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));panel.addView(TvUi.text(a,"左右分组 · 上下选择 · 确定换台",16,true));
        digits=TvUi.text(a,"",32,false);digits.setPadding(TvUi.dp(a,12),TvUi.dp(a,8),TvUi.dp(a,12),TvUi.dp(a,8));digits.setBackground(TvUi.glass(a,false));digits.setVisibility(View.GONE);FrameLayout.LayoutParams dp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.LEFT);dp.setMargins(TvUi.dp(a,30),TvUi.dp(a,25),0,0);stage.addView(digits,dp);
    }
    void guide(CinemaEpg value){guide=value;if(open())render();}
    boolean open(){return panel.getVisibility()==View.VISIBLE;}
    void show(int current){if(closed||channels.isEmpty())return;selected=Math.max(0,Math.min(current,channels.size()-1));group=groups.indexOf(channels.get(selected).group);panel.setVisibility(View.VISIBLE);render();reset();}
    void hide(){entered="";digits.setVisibility(View.GONE);main.removeCallbacks(tune);if(!open())return;panel.setVisibility(View.GONE);main.removeCallbacks(hide);dismissed.run();}
    private void reset(){main.removeCallbacks(hide);main.postDelayed(hide,5000);}
    private void render(){heading.setText("‹  "+groups.get(group)+"  ›");visible.clear();rows.removeAllViews();for(int i=0;i<channels.size();i++)if(channels.get(i).group.equals(groups.get(group)))visible.add(i);if(!visible.contains(selected))selected=visible.get(0);for(int index:visible){CinemaCatalog.Channel c=channels.get(index);Button row=TvUi.button(activity,numbers[index]+"  "+c.name,()->{main.removeCallbacks(hide);select.select(index);});row.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,28*activity.getResources().getDisplayMetrics().heightPixels/1080f);row.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);row.setSingleLine(true);row.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Math.max(TvUi.dp(activity,44),Math.round(activity.getResources().getDisplayMetrics().heightPixels*.065f)));p.setMargins(0,0,0,TvUi.dp(activity,5));rows.addView(row,p);row.setOnFocusChangeListener((v,f)->{if(f){selected=index;updatePreview();reset();}});if(index==selected)row.post(()->focusRow(row,index));}updatePreview();}
    private void focusRow(View row,int index){if(!closed&&open()&&selected==index&&row.getParent()==rows)row.requestFocus();}
    private void updatePreview(){CinemaCatalog.Channel c=channels.get(selected);String programme=guide.nowNext(c,System.currentTimeMillis());preview.setText(c.name+(programme.isEmpty()?"\n暂无节目单":"\n"+programme));logo.setImageDrawable(null);if(!c.logo.isEmpty())artwork.bind(logo,c.logo,"",allowHttp);}
    boolean key(KeyEvent event){int code=event.getKeyCode();        if(code>=KeyEvent.KEYCODE_0&&code<=KeyEvent.KEYCODE_9){if(event.getAction()==KeyEvent.ACTION_DOWN){if(open())reset();entered=(entered+String.valueOf(code-KeyEvent.KEYCODE_0));if(entered.length()>4)entered=entered.substring(entered.length()-4);digits.setText(entered);digits.setVisibility(View.VISIBLE);main.removeCallbacks(tune);main.postDelayed(tune,1200);}return true;}if(!entered.isEmpty()&&(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER)){if(event.getAction()==KeyEvent.ACTION_DOWN&&open())reset();if(event.getAction()==KeyEvent.ACTION_UP)tune();return true;}if(open()){if(event.getAction()==KeyEvent.ACTION_DOWN)reset();if(code==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)hide();return true;}if(code==KeyEvent.KEYCODE_DPAD_LEFT||code==KeyEvent.KEYCODE_DPAD_RIGHT){if(event.getAction()==KeyEvent.ACTION_DOWN){group=(group+(code==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1)+groups.size())%groups.size();render();}return true;}if(code==KeyEvent.KEYCODE_DPAD_UP||code==KeyEvent.KEYCODE_DPAD_DOWN){if(event.getAction()==KeyEvent.ACTION_DOWN){int at=visible.indexOf(selected),next=at+(code==KeyEvent.KEYCODE_DPAD_DOWN?1:-1);if(next>=0&&next<visible.size()){selected=visible.get(next);final int chosenIndex=selected;View chosen=rows.getChildAt(next);chosen.requestFocus();chosen.post(()->focusRow(chosen,chosenIndex));rows.getChildAt(next).requestRectangleOnScreen(new android.graphics.Rect(0,0,rows.getChildAt(next).getWidth(),rows.getChildAt(next).getHeight()));}}return true;}if(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER){if(event.getAction()==KeyEvent.ACTION_UP)select.select(selected);return true;}}
        return false;
    }
    private void tune(){main.removeCallbacks(tune);int value;try{value=Integer.parseInt(entered);}catch(Exception e){return;}entered="";for(int i=0;i<numbers.length;i++)if(numbers[i]==value){digits.setVisibility(View.GONE);select.select(i);return;}digits.setText("没有这个频道");main.postDelayed(()->digits.setVisibility(View.GONE),1800);}
    public void close(){closed=true;main.removeCallbacksAndMessages(null);}
}
